/**
 * Expo config plugin for react-native-nexconn.
 *
 * The official Nexconn Android SDK is published on Nexconn's own Maven
 * repository. Gradle resolves an app's dependencies with the app's
 * repositories, so prebuild has to declare it in the generated project.
 * iOS needs no changes: the SDK comes from the CocoaPods trunk.
 */
const REPOSITORY_URL = 'https://maven.nexconn.ai/repository/maven-releases/';
const BLOCK = `
// @generated by react-native-nexconn
allprojects {
    repositories {
        maven { url "${REPOSITORY_URL}" }
    }
}
`;

function addNexconnRepository(contents) {
  return contents.includes(REPOSITORY_URL) ? contents : contents + BLOCK;
}

function withNexconn(config) {
  // Resolved from the app as well, so the plugin also works when this package
  // is linked from outside the app's node_modules (monorepos, workspaces).
  const { withProjectBuildGradle } = require(
    require.resolve('expo/config-plugins', {
      paths: [__dirname, process.cwd()],
    })
  );
  return withProjectBuildGradle(config, (gradleConfig) => {
    if (gradleConfig.modResults.language !== 'groovy') {
      throw new Error(
        'react-native-nexconn: expected a Groovy android/build.gradle. Add the ' +
          `Maven repository ${REPOSITORY_URL} to the project manually.`
      );
    }
    gradleConfig.modResults.contents = addNexconnRepository(
      gradleConfig.modResults.contents
    );
    return gradleConfig;
  });
}

module.exports = withNexconn;
module.exports.addNexconnRepository = addNexconnRepository;
